package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"github.com/jmoiron/sqlx"
	"golang.org/x/crypto/bcrypt"
)

// Options carries the settings shared by every scenario.
type Options struct {
	// Password is the plain password of every seeded account. It comes from
	// SEED_PASSWORD, is never printed and is only kept as its bcrypt hash.
	Password string
	// PasswordHash is the bcrypt hash of Password. Execute fills it in.
	PasswordHash string
	// Issues is the number of issues generated by the scale scenario.
	Issues int
	// ForceReset empties the application tables before seeding.
	ForceReset bool
	// Out receives progress messages. Nil discards them.
	Out io.Writer
}

// Scenario is a deterministic dataset that can be seeded into a migrated database.
type Scenario interface {
	Name() string
	Run(ctx context.Context, db *sqlx.DB, opts Options) error
}

var registry = map[string]Scenario{}

// Register adds a scenario to the registry. Scenario files call it from init.
func Register(s Scenario) {
	if _, dup := registry[s.Name()]; dup {
		panic("seed: duplicate scenario " + s.Name())
	}
	registry[s.Name()] = s
}

func lookupScenario(name string) (Scenario, error) {
	s, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("escenario desconocido %q (disponibles: %s)", name, strings.Join(scenarioNames(), ", "))
	}
	return s, nil
}

func scenarioNames() []string {
	names := make([]string, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// errNotEmpty is returned when the database already has users and --force-reset was not given.
var errNotEmpty = errors.New("la base de datos ya tiene usuarios; usa --force-reset para vaciar las tablas de la aplicacion y volver a sembrar")

// appTables lists every application table, children before parents. schema_migrations is never touched.
var appTables = []string{
	"domain_events", "event_cursors", "favorites", "recent_items", "project_permissions", "project_team_roles",
	"notification_preferences", "notifications", "user_sessions",
	"comment_mentions", "comments", "activities", "watchers", "issue_links", "issue_votes", "attachments",
	"issue_labels", "issue_components", "saved_filters", "issue_status_history", "issues", "sprints",
	"board_quick_filters", "board_swimlanes", "board_column_statuses", "board_columns", "boards", "workflows", "statuses",
	"labels", "components", "project_members", "projects",
	"team_members", "teams", "organization_invitations", "organization_members", "organizations", "users",
}

// Execute hashes the password, prepares the database and runs the scenario.
func Execute(ctx context.Context, db *sqlx.DB, sc Scenario, opts Options) error {
	if opts.Password == "" {
		return errors.New("falta la contrasena de las cuentas de prueba")
	}
	if opts.Out == nil {
		opts.Out = io.Discard
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(opts.Password), bcrypt.DefaultCost)
	if err != nil {
		return fmt.Errorf("generar hash de contrasena: %w", err)
	}
	opts.PasswordHash = string(hash)

	if err := prepareDatabase(ctx, db, opts.ForceReset); err != nil {
		return err
	}
	fmt.Fprintf(opts.Out, "Sembrando escenario %q...\n", sc.Name())
	if err := sc.Run(ctx, db, opts); err != nil {
		return fmt.Errorf("escenario %q: %w", sc.Name(), err)
	}
	fmt.Fprintf(opts.Out, "Escenario %q sembrado correctamente.\n", sc.Name())
	return nil
}

// prepareDatabase refuses to seed a database that already has users, unless
// forceReset is set, in which case every application table is truncated in one
// statement (TRUNCATE with CASCADE handles foreign keys regardless of order).
func prepareDatabase(ctx context.Context, db *sqlx.DB, forceReset bool) error {
	if forceReset {
		if err := guardRealAccounts(ctx, db); err != nil {
			return err
		}
		if _, err := db.ExecContext(ctx, "TRUNCATE TABLE "+strings.Join(appTables, ", ")+" RESTART IDENTITY CASCADE"); err != nil {
			return fmt.Errorf("vaciar tablas: %w", err)
		}
		return nil
	}
	var users int
	if err := db.GetContext(ctx, &users, `SELECT count(*) FROM users`); err != nil {
		return fmt.Errorf("contar usuarios: %w", err)
	}
	if users > 0 {
		return errNotEmpty
	}
	return nil
}

// errRealAccounts is returned when a reset would delete accounts that were not created by the seed.
var errRealAccounts = errors.New("la base contiene cuentas que no son de la semilla (correos fuera de @corelog.test y @corelog.local); un reinicio las borraria. Haz un volcado y define SEED_ALLOW_DATA_LOSS=yes si de verdad quieres continuar")

// guardRealAccounts refuses to truncate a database that holds hand-made accounts unless the caller
// opts in with SEED_ALLOW_DATA_LOSS=yes.
func guardRealAccounts(ctx context.Context, db *sqlx.DB) error {
	if os.Getenv("SEED_ALLOW_DATA_LOSS") == "yes" {
		return nil
	}
	var real int
	if err := db.GetContext(ctx, &real, `SELECT count(*) FROM users WHERE email NOT LIKE '%@corelog.test' AND email NOT LIKE '%@corelog.local'`); err != nil {
		return fmt.Errorf("comprobar cuentas reales: %w", err)
	}
	if real > 0 {
		return errRealAccounts
	}
	return nil
}
